import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { AuthGuard } from './core/guards/auth.guard';
import { AuthComponent } from './features/auth/auth.component';
import { PreparationComponent } from './features/preparation/preparation.component';
import { ShoppingComponent } from './features/shopping/shopping.component';
import { AdminComponent } from './features/admin/admin.component';

const routes: Routes = [
  { path: '', redirectTo: '/preparation', pathMatch: 'full' },
  { path: 'auth', component: AuthComponent },
  { path: 'preparation', component: PreparationComponent, canActivate: [AuthGuard] },
  { path: 'shopping', component: ShoppingComponent, canActivate: [AuthGuard] },
  { path: 'admin', component: AdminComponent, canActivate: [AuthGuard] },
  { path: '**', redirectTo: '/preparation' }
];

@NgModule({
  imports: [RouterModule.forRoot(routes)],
  exports: [RouterModule]
})
export class AppRoutingModule { }
