import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { AccountService } from '../../core/services/account.service';
import { SyncService } from '../../core/services/sync.service';

type AuthMode = 'create' | 'join';

@Component({
  selector: 'app-auth',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './auth.component.html',
  styleUrls: ['./auth.component.scss']
})
export class AuthComponent {
  mode: AuthMode = 'create';
  pin: string = '';
  code: string = '';
  generatedCode: string = '';
  loading: boolean = false;
  error: string = '';

  constructor(
    private accountService: AccountService,
    private syncService: SyncService,
    private router: Router
  ) {}

  switchMode(newMode: AuthMode): void {
    this.mode = newMode;
    this.error = '';
    this.pin = '';
    this.code = '';
    this.generatedCode = '';
  }

  async createAccount(): Promise<void> {
    this.loading = true;
    this.error = '';

    try {
      const account = await this.accountService.createNewAccount(
        this.pin || undefined
      );

      this.generatedCode = account.code;

      await this.syncService.initialize();

      setTimeout(() => {
        this.router.navigate(['/preparation']);
      }, 3000);
    } catch (err: any) {
      this.error = err.message || 'Failed to create account';
      this.loading = false;
    }
  }

  async joinAccount(): Promise<void> {
    if (!this.code.trim()) {
      this.error = 'Please enter an account code';
      return;
    }

    this.loading = true;
    this.error = '';

    try {
      await this.accountService.joinExistingAccount(
        this.code,
        this.pin || undefined
      );

      await this.syncService.initialize();

      this.router.navigate(['/preparation']);
    } catch (err: any) {
      this.error = err.message || 'Failed to join account';
      this.loading = false;
    }
  }

  copyCode(): void {
    if (this.generatedCode) {
      navigator.clipboard.writeText(this.generatedCode);
    }
  }

  formatCodeInput(): void {
    let cleaned = this.code.toUpperCase().replace(/[^A-Z0-9]/g, '');

    if (cleaned.length > 8) {
      cleaned = cleaned.substring(0, 8);
    }

    if (cleaned.length > 4) {
      this.code = `${cleaned.substring(0, 4)}-${cleaned.substring(4)}`;
    } else {
      this.code = cleaned;
    }
  }
}
