import { Injectable } from '@angular/core';
import { Router } from '@angular/router';
import { StorageService } from './storage.service';
import { SupabaseService } from './supabase.service';
import { Account } from '../models/account.model';

@Injectable({
  providedIn: 'root'
})
export class AccountService {
  private readonly CODE_CHARS = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';

  constructor(
    private storage: StorageService,
    private supabase: SupabaseService,
    private router: Router
  ) {}

  generateCode(): string {
    let code = '';
    for (let i = 0; i < 8; i++) {
      if (i === 4) {
        code += '-';
      }
      const randomIndex = Math.floor(Math.random() * this.CODE_CHARS.length);
      code += this.CODE_CHARS[randomIndex];
    }
    return code;
  }

  async hashPin(pin: string): Promise<string> {
    const encoder = new TextEncoder();
    const data = encoder.encode(pin);
    const hashBuffer = await crypto.subtle.digest('SHA-256', data);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    const hashHex = hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
    return hashHex;
  }

  async createNewAccount(pin?: string): Promise<Account> {
    const code = this.generateCode();
    const pinHash = pin ? await this.hashPin(pin) : undefined;

    const response = await this.supabase.createAccount(code, pinHash);

    if (!response.success) {
      throw new Error(response.error_message || 'Failed to create account');
    }

    const account: Account = {
      id: response.account_id,
      code: response.code
    };

    this.storage.setAccount(account);
    return account;
  }

  async joinExistingAccount(code: string, pin?: string): Promise<Account> {
    const formattedCode = this.formatCode(code);
    const pinHash = pin ? await this.hashPin(pin) : undefined;

    const response = await this.supabase.joinAccount(formattedCode, pinHash);

    if (!response.success) {
      throw new Error(response.error_message || 'Failed to join account');
    }

    const account: Account = {
      id: response.account_id,
      code: formattedCode
    };

    this.storage.setAccount(account);
    return account;
  }

  isLoggedIn(): boolean {
    return this.storage.getAccount() !== null;
  }

  getCurrentAccount(): Account | null {
    return this.storage.getAccount();
  }

  logout(): void {
    this.storage.clear();
    this.router.navigate(['/auth']);
  }

  private formatCode(code: string): string {
    const cleaned = code.toUpperCase().replace(/[^A-Z0-9]/g, '');

    if (cleaned.length !== 8) {
      throw new Error('Code must be 8 characters');
    }

    return `${cleaned.substring(0, 4)}-${cleaned.substring(4)}`;
  }
}
