import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router, NavigationEnd } from '@angular/router';
import { Subscription, filter } from 'rxjs';
import { StorageService } from '../../../core/services/storage.service';
import { SyncService, SyncStatus } from '../../../core/services/sync.service';

type ViewMode = 'preparation' | 'shopping';

@Component({
  selector: 'app-header',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './header.component.html',
  styleUrls: ['./header.component.scss']
})
export class HeaderComponent implements OnInit, OnDestroy {
  currentMode: ViewMode = 'preparation';
  fontSize: number = 16;
  syncStatus: SyncStatus = 'synced';

  private syncSubscription?: Subscription;
  private routerSubscription?: Subscription;

  constructor(
    private storage: StorageService,
    private sync: SyncService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.fontSize = this.storage.getFontSize();

    this.syncSubscription = this.sync.getSyncStatus().subscribe(status => {
      this.syncStatus = status;
    });

    this.routerSubscription = this.router.events
      .pipe(filter(event => event instanceof NavigationEnd))
      .subscribe((event: any) => {
        if (event.url.includes('/shopping')) {
          this.currentMode = 'shopping';
        } else if (event.url.includes('/preparation')) {
          this.currentMode = 'preparation';
        }
      });

    const currentUrl = this.router.url;
    if (currentUrl.includes('/shopping')) {
      this.currentMode = 'shopping';
    } else if (currentUrl.includes('/preparation')) {
      this.currentMode = 'preparation';
    }
  }

  ngOnDestroy(): void {
    this.syncSubscription?.unsubscribe();
    this.routerSubscription?.unsubscribe();
  }

  toggleMode(): void {
    if (this.currentMode === 'preparation') {
      this.router.navigate(['/shopping']);
    } else {
      this.router.navigate(['/preparation']);
    }
  }

  increaseFontSize(): void {
    if (this.fontSize < 24) {
      this.fontSize++;
      this.storage.setFontSize(this.fontSize);
      this.applyFontSize();
    }
  }

  decreaseFontSize(): void {
    if (this.fontSize > 12) {
      this.fontSize--;
      this.storage.setFontSize(this.fontSize);
      this.applyFontSize();
    }
  }

  goToAdmin(): void {
    this.router.navigate(['/admin']);
  }

  private applyFontSize(): void {
    document.documentElement.style.setProperty('--item-font-size', `${this.fontSize}px`);
  }

  getSyncStatusClass(): string {
    switch (this.syncStatus) {
      case 'synced':
        return 'sync-synced';
      case 'pending':
        return 'sync-pending';
      case 'error':
        return 'sync-error';
      default:
        return '';
    }
  }

  getSyncStatusTitle(): string {
    switch (this.syncStatus) {
      case 'synced':
        return 'Synchronisé';
      case 'pending':
        return 'Synchronisation en attente';
      case 'error':
        return 'Erreur de synchronisation';
      default:
        return '';
    }
  }
}
