import { Injectable } from '@angular/core';
import { createClient, SupabaseClient, RealtimeChannel } from '@supabase/supabase-js';
import { environment } from '../../../environments/environment';
import { Item } from '../models/item.model';
import { CreateAccountResponse, JoinAccountResponse } from '../models/account.model';

@Injectable({
  providedIn: 'root'
})
export class SupabaseService {
  private supabase: SupabaseClient;
  private realtimeChannel: RealtimeChannel | null = null;
  private currentAccountId: string | null = null;

  constructor() {
    this.supabase = this.createSupabaseClient();
  }

  private createSupabaseClient(accountId?: string): SupabaseClient {
    const headers: Record<string, string> = {};

    if (accountId) {
      headers['x-account-id'] = accountId;
    }

    return createClient(
      environment.supabase.url,
      environment.supabase.anonKey,
      {
        global: {
          headers: headers
        }
      }
    );
  }

  setAccountId(accountId: string): void {
    if (this.currentAccountId !== accountId) {
      this.currentAccountId = accountId;
      // Recréer le client avec le nouveau header
      this.supabase = this.createSupabaseClient(accountId);
    }
  }

  async createAccount(code: string, pinHash?: string): Promise<CreateAccountResponse> {
    const { data, error } = await this.supabase.rpc('create_account', {
      p_code: code,
      p_pin_hash: pinHash || null
    });

    if (error) {
      throw new Error(error.message);
    }

    return data[0] as CreateAccountResponse;
  }

  async joinAccount(code: string, pinHash?: string): Promise<JoinAccountResponse> {
    const { data, error } = await this.supabase.rpc('join_account', {
      p_code: code,
      p_pin_hash: pinHash || null
    });

    if (error) {
      throw new Error(error.message);
    }

    return data[0] as JoinAccountResponse;
  }

  async fetchItems(accountId: string): Promise<Item[]> {
    const { data, error } = await this.supabase
      .from('items')
      .select('*')
      .eq('account_id', accountId)
      .order('sort_order', { ascending: true });

    if (error) {
      throw new Error(error.message);
    }

    return (data || []).map(item => this.mapDbItemToItem(item));
  }

  async upsertItem(item: Item, accountId: string): Promise<void> {
    const dbItem = this.mapItemToDbItem(item);

    const { error } = await this.supabase
      .from('items')
      .upsert({
        ...dbItem,
        account_id: accountId
      }, {
        onConflict: 'id'
      });

    if (error) {
      throw new Error(error.message);
    }
  }

  async deleteItem(itemId: string, accountId: string): Promise<void> {
    const { error } = await this.supabase
      .from('items')
      .delete()
      .eq('id', itemId)
      .eq('account_id', accountId);

    if (error) {
      throw new Error(error.message);
    }
  }

  subscribeToChanges(
    accountId: string,
    callback: (payload: any) => void
  ): RealtimeChannel {
    if (this.realtimeChannel) {
      this.supabase.removeChannel(this.realtimeChannel);
    }

    this.realtimeChannel = this.supabase
      .channel(`items:account_id=eq.${accountId}`)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'items',
          filter: `account_id=eq.${accountId}`
        },
        callback
      )
      .subscribe();

    return this.realtimeChannel;
  }

  unsubscribeFromChanges(): void {
    if (this.realtimeChannel) {
      this.supabase.removeChannel(this.realtimeChannel);
      this.realtimeChannel = null;
    }
  }

  private mapDbItemToItem(dbItem: any): Item {
    return {
      id: dbItem.id,
      accountId: dbItem.account_id,
      name: dbItem.name,
      quantity: dbItem.quantity,
      status: dbItem.status,
      sortOrder: dbItem.sort_order,
      updatedAt: new Date(dbItem.updated_at),
      pendingSync: false
    };
  }

  private mapItemToDbItem(item: Item): any {
    return {
      id: item.id,
      name: item.name,
      quantity: item.quantity,
      status: item.status,
      sort_order: item.sortOrder,
      updated_at: item.updatedAt.toISOString()
    };
  }
}
