import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router } from '@angular/router';
import { Subscription } from 'rxjs';
import { AccountService } from '../../core/services/account.service';
import { SyncService, SyncStatus } from '../../core/services/sync.service';
import { Account } from '../../core/models/account.model';
import { HeaderComponent } from '../../shared/components/header/header.component';

@Component({
  selector: 'app-admin',
  standalone: true,
  imports: [CommonModule, HeaderComponent],
  templateUrl: './admin.component.html',
  styleUrls: ['./admin.component.scss']
})
export class AdminComponent implements OnInit, OnDestroy {
  account: Account | null = null;
  syncStatus: SyncStatus = 'synced';
  resetConfirmation: boolean = false;

  private syncSubscription?: Subscription;

  constructor(
    private accountService: AccountService,
    private syncService: SyncService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.account = this.accountService.getCurrentAccount();

    this.syncSubscription = this.syncService.getSyncStatus().subscribe(status => {
      this.syncStatus = status;
    });
  }

  ngOnDestroy(): void {
    this.syncSubscription?.unsubscribe();
  }

  copyCode(): void {
    if (this.account?.code) {
      navigator.clipboard.writeText(this.account.code);
    }
  }

  getSyncStatusText(): string {
    switch (this.syncStatus) {
      case 'synced':
        return 'Synchronisé';
      case 'pending':
        return 'Synchronisation en attente';
      case 'error':
        return 'Erreur de connexion';
      default:
        return 'Inconnu';
    }
  }

  getSyncStatusClass(): string {
    switch (this.syncStatus) {
      case 'synced':
        return 'status-synced';
      case 'pending':
        return 'status-pending';
      case 'error':
        return 'status-error';
      default:
        return '';
    }
  }

  async retrySync(): Promise<void> {
    await this.syncService.retryPendingSync();
  }

  startReset(): void {
    this.resetConfirmation = true;
  }

  cancelReset(): void {
    this.resetConfirmation = false;
  }

  confirmReset(): void {
    this.accountService.logout();
  }

  goBack(): void {
    this.router.navigate(['/preparation']);
  }
}
