import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable, fromEvent, merge } from 'rxjs';
import { StorageService } from './storage.service';
import { SupabaseService } from './supabase.service';
import { AccountService } from './account.service';
import { Item, CreateItemDto, UpdateItemDto } from '../models/item.model';

export type SyncStatus = 'synced' | 'pending' | 'error';

@Injectable({
  providedIn: 'root'
})
export class SyncService {
  private items$ = new BehaviorSubject<Item[]>([]);
  private syncStatus$ = new BehaviorSubject<SyncStatus>('synced');

  constructor(
    private storage: StorageService,
    private supabase: SupabaseService,
    private account: AccountService
  ) {
    this.setupOnlineListener();
  }

  async initialize(): Promise<void> {
    const currentAccount = this.account.getCurrentAccount();
    if (!currentAccount) {
      return;
    }

    // Configurer le client Supabase avec l'account_id dans les headers
    this.supabase.setAccountId(currentAccount.id);

    const localItems = this.storage.getItems();
    this.items$.next(localItems);

    try {
      const remoteItems = await this.supabase.fetchItems(currentAccount.id);
      const mergedItems = this.mergeItems(localItems, remoteItems);

      this.items$.next(mergedItems);
      this.storage.setItems(mergedItems);

      await this.retryPendingSync();

      this.supabase.subscribeToChanges(currentAccount.id, (payload) => {
        this.handleRealtimeUpdate(payload);
      });
    } catch (error) {
      console.error('Failed to sync with server:', error);
      this.syncStatus$.next('error');
    }
  }

  getItems(): Observable<Item[]> {
    return this.items$.asObservable();
  }

  getSyncStatus(): Observable<SyncStatus> {
    return this.syncStatus$.asObservable();
  }

  async addItem(dto: CreateItemDto): Promise<Item> {
    const currentAccount = this.account.getCurrentAccount();
    if (!currentAccount) {
      throw new Error('No account found');
    }

    const newItem: Item = {
      id: crypto.randomUUID(),
      accountId: currentAccount.id,
      name: dto.name,
      quantity: dto.quantity || 1,
      status: dto.status || 'to_buy',
      sortOrder: dto.sortOrder,
      updatedAt: new Date(),
      pendingSync: false
    };

    const currentItems = this.items$.value;
    const updatedItems = [...currentItems, newItem];

    this.items$.next(updatedItems);
    this.storage.setItems(updatedItems);

    try {
      await this.supabase.upsertItem(newItem, currentAccount.id);
    } catch (error) {
      console.error('Failed to sync new item:', error);
      newItem.pendingSync = true;
      this.items$.next(updatedItems);
      this.storage.setItems(updatedItems);
      this.syncStatus$.next('pending');
    }

    return newItem;
  }

  async updateItem(itemId: string, dto: UpdateItemDto): Promise<void> {
    const currentAccount = this.account.getCurrentAccount();
    if (!currentAccount) {
      throw new Error('No account found');
    }

    const currentItems = this.items$.value;
    const itemIndex = currentItems.findIndex(i => i.id === itemId);

    if (itemIndex === -1) {
      throw new Error('Item not found');
    }

    const updatedItem: Item = {
      ...currentItems[itemIndex],
      ...dto,
      updatedAt: new Date(),
      pendingSync: false
    };

    const updatedItems = [...currentItems];
    updatedItems[itemIndex] = updatedItem;

    this.items$.next(updatedItems);
    this.storage.setItems(updatedItems);

    try {
      await this.supabase.upsertItem(updatedItem, currentAccount.id);
    } catch (error) {
      console.error('Failed to sync updated item:', error);
      updatedItem.pendingSync = true;
      updatedItems[itemIndex] = updatedItem;
      this.items$.next(updatedItems);
      this.storage.setItems(updatedItems);
      this.syncStatus$.next('pending');
    }
  }

  async deleteItem(itemId: string): Promise<void> {
    const currentAccount = this.account.getCurrentAccount();
    if (!currentAccount) {
      throw new Error('No account found');
    }

    const currentItems = this.items$.value;
    const updatedItems = currentItems.filter(i => i.id !== itemId);

    this.items$.next(updatedItems);
    this.storage.setItems(updatedItems);

    try {
      await this.supabase.deleteItem(itemId, currentAccount.id);
    } catch (error) {
      console.error('Failed to sync item deletion:', error);
      this.syncStatus$.next('error');
    }
  }

  async reorderItems(items: Item[]): Promise<void> {
    const currentAccount = this.account.getCurrentAccount();
    if (!currentAccount) {
      throw new Error('No account found');
    }

    const reorderedItems = items.map((item, index) => ({
      ...item,
      sortOrder: index,
      updatedAt: new Date()
    }));

    this.items$.next(reorderedItems);
    this.storage.setItems(reorderedItems);

    try {
      for (const item of reorderedItems) {
        await this.supabase.upsertItem(item, currentAccount.id);
      }
    } catch (error) {
      console.error('Failed to sync reordering:', error);
      this.syncStatus$.next('error');
    }
  }

  async retryPendingSync(): Promise<void> {
    const currentAccount = this.account.getCurrentAccount();
    if (!currentAccount) {
      return;
    }

    const currentItems = this.items$.value;
    const pendingItems = currentItems.filter(i => i.pendingSync);

    if (pendingItems.length === 0) {
      this.syncStatus$.next('synced');
      return;
    }

    let hasErrors = false;

    for (const item of pendingItems) {
      try {
        await this.supabase.upsertItem(item, currentAccount.id);
        item.pendingSync = false;
      } catch (error) {
        console.error('Failed to sync pending item:', error);
        hasErrors = true;
      }
    }

    this.items$.next([...currentItems]);
    this.storage.setItems(currentItems);

    this.syncStatus$.next(hasErrors ? 'error' : 'synced');
  }

  private mergeItems(localItems: Item[], remoteItems: Item[]): Item[] {
    const mergedMap = new Map<string, Item>();

    for (const item of localItems) {
      mergedMap.set(item.id, item);
    }

    for (const item of remoteItems) {
      const existing = mergedMap.get(item.id);
      if (!existing || item.updatedAt > existing.updatedAt) {
        mergedMap.set(item.id, item);
      }
    }

    return Array.from(mergedMap.values()).sort((a, b) => a.sortOrder - b.sortOrder);
  }

  private handleRealtimeUpdate(payload: any): void {
    const currentItems = this.items$.value;
    let updatedItems = [...currentItems];

    if (payload.eventType === 'INSERT' || payload.eventType === 'UPDATE') {
      const dbItem = payload.new;
      const item: Item = {
        id: dbItem.id,
        accountId: dbItem.account_id,
        name: dbItem.name,
        quantity: dbItem.quantity,
        status: dbItem.status,
        sortOrder: dbItem.sort_order,
        updatedAt: new Date(dbItem.updated_at),
        pendingSync: false
      };

      const existingIndex = updatedItems.findIndex(i => i.id === item.id);

      if (existingIndex >= 0) {
        const existing = updatedItems[existingIndex];
        if (item.updatedAt > existing.updatedAt) {
          updatedItems[existingIndex] = item;
        }
      } else {
        updatedItems.push(item);
      }
    } else if (payload.eventType === 'DELETE') {
      const deletedId = payload.old.id;
      updatedItems = updatedItems.filter(i => i.id !== deletedId);
    }

    updatedItems.sort((a, b) => a.sortOrder - b.sortOrder);

    this.items$.next(updatedItems);
    this.storage.setItems(updatedItems);
  }

  private setupOnlineListener(): void {
    if (typeof window !== 'undefined' && 'ononline' in window) {
      fromEvent(window, 'online').subscribe(() => {
        this.retryPendingSync();
      });
    }
  }

  destroy(): void {
    this.supabase.unsubscribeFromChanges();
  }
}
