import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Subscription } from 'rxjs';
import { SyncService } from '../../core/services/sync.service';
import { Item, ItemStatus } from '../../core/models/item.model';
import { HeaderComponent } from '../../shared/components/header/header.component';

@Component({
  selector: 'app-shopping',
  standalone: true,
  imports: [CommonModule, HeaderComponent],
  templateUrl: './shopping.component.html',
  styleUrls: ['./shopping.component.scss']
})
export class ShoppingComponent implements OnInit, OnDestroy {
  items: Item[] = [];
  shoppingItems: Item[] = [];

  private itemsSubscription?: Subscription;

  constructor(private sync: SyncService) {}

  ngOnInit(): void {
    this.itemsSubscription = this.sync.getItems().subscribe(items => {
      this.items = items;
      this.shoppingItems = items.filter(item => item.quantity > 0);
    });
  }

  ngOnDestroy(): void {
    this.itemsSubscription?.unsubscribe();
  }

  async toggleItemStatus(item: Item): Promise<void> {
    const statusCycle: ItemStatus[] = ['to_buy', 'found', 'not_found'];
    const currentIndex = statusCycle.indexOf(item.status);
    const nextIndex = (currentIndex + 1) % statusCycle.length;
    const nextStatus = statusCycle[nextIndex];

    await this.sync.updateItem(item.id, {
      status: nextStatus
    });
  }

  getItemStatusClass(item: Item): string {
    switch (item.status) {
      case 'to_buy':
        return 'status-to-buy';
      case 'found':
        return 'status-found';
      case 'not_found':
        return 'status-not-found';
      default:
        return '';
    }
  }

  getItemStatusText(item: Item): string {
    switch (item.status) {
      case 'to_buy':
        return 'À acheter';
      case 'found':
        return 'Trouvé';
      case 'not_found':
        return 'Non trouvé';
      default:
        return '';
    }
  }

  isStrikethrough(item: Item): boolean {
    return item.status === 'found' || item.status === 'not_found';
  }
}
