import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Subscription } from 'rxjs';
import { SyncService } from '../../core/services/sync.service';
import { Item } from '../../core/models/item.model';
import { HeaderComponent } from '../../shared/components/header/header.component';

@Component({
  selector: 'app-preparation',
  standalone: true,
  imports: [CommonModule, FormsModule, HeaderComponent],
  templateUrl: './preparation.component.html',
  styleUrls: ['./preparation.component.scss']
})
export class PreparationComponent implements OnInit, OnDestroy {
  items: Item[] = [];
  newItemName: string = '';
  editingItemId: string | null = null;
  editingItemName: string = '';

  private itemsSubscription?: Subscription;

  constructor(private sync: SyncService) {}

  ngOnInit(): void {
    this.itemsSubscription = this.sync.getItems().subscribe(items => {
      this.items = items;
    });
  }

  ngOnDestroy(): void {
    this.itemsSubscription?.unsubscribe();
  }

  async addItem(): Promise<void> {
    if (!this.newItemName.trim()) {
      return;
    }

    const maxSortOrder = this.items.length > 0
      ? Math.max(...this.items.map(i => i.sortOrder))
      : -1;

    await this.sync.addItem({
      name: this.newItemName.trim(),
      quantity: 1,
      sortOrder: maxSortOrder + 1
    });

    this.newItemName = '';
  }

  startEditItem(item: Item): void {
    this.editingItemId = item.id;
    this.editingItemName = item.name;
  }

  async saveEditItem(item: Item): Promise<void> {
    if (this.editingItemName.trim() && this.editingItemName !== item.name) {
      await this.sync.updateItem(item.id, {
        name: this.editingItemName.trim()
      });
    }

    this.editingItemId = null;
    this.editingItemName = '';
  }

  cancelEditItem(): void {
    this.editingItemId = null;
    this.editingItemName = '';
  }

  async increaseQuantity(item: Item): Promise<void> {
    if (item.quantity < 1000) {
      await this.sync.updateItem(item.id, {
        quantity: item.quantity + 1
      });
    }
  }

  async decreaseQuantity(item: Item): Promise<void> {
    if (item.quantity > 0) {
      await this.sync.updateItem(item.id, {
        quantity: item.quantity - 1
      });
    }
  }

  async deleteItem(item: Item): Promise<void> {
    if (confirm(`Supprimer "${item.name}" de la liste?`)) {
      await this.sync.deleteItem(item.id);
    }
  }

  async moveUp(item: Item): Promise<void> {
    const currentIndex = this.items.findIndex(i => i.id === item.id);

    if (currentIndex > 0) {
      const newItems = [...this.items];
      [newItems[currentIndex], newItems[currentIndex - 1]] =
        [newItems[currentIndex - 1], newItems[currentIndex]];

      await this.sync.reorderItems(newItems);
    }
  }

  async moveDown(item: Item): Promise<void> {
    const currentIndex = this.items.findIndex(i => i.id === item.id);

    if (currentIndex < this.items.length - 1) {
      const newItems = [...this.items];
      [newItems[currentIndex], newItems[currentIndex + 1]] =
        [newItems[currentIndex + 1], newItems[currentIndex]];

      await this.sync.reorderItems(newItems);
    }
  }

  canMoveUp(item: Item): boolean {
    const index = this.items.findIndex(i => i.id === item.id);
    return index > 0;
  }

  canMoveDown(item: Item): boolean {
    const index = this.items.findIndex(i => i.id === item.id);
    return index < this.items.length - 1;
  }

  isEditing(item: Item): boolean {
    return this.editingItemId === item.id;
  }
}
